//! Differential tests of the module-level parser against LLVM
//! (`spec/ll.md` §10): what `hod_ll` reads out of a module is compared
//! with what `llvm-as | llvm-dis` prints for it and with the object `llc`
//! makes of it, over a corpus generated by clang 19 and 22 and a set of
//! hand-written modules.

#[path = "../common/mod.rs"]
mod common;

mod bodies;
mod canonical;
mod flags;
mod objects;

use std::collections::{BTreeMap, BTreeSet};

use common::{corpus, parse, parsed};

/// What clang's output may contain that `hod_ir` cannot represent
/// (`spec/ll.md` §3.4). A name appearing here that is not in this list
/// fails the test: every unsupported construct of the corpus is known by
/// name.
const CLANG_UNSUPPORTED: &[&str] = &[
    "attr:convergent",
    "attr:no_caller_saved_registers",
    "attr:nocf_check",
    "attr:noduplicate",
    "attr:speculative_load_hardening",
    "special-global:llvm.global.annotations",
];

/// §10 acceptance: everything `llvm-as` accepts in the corpus parses, in
/// the dialect of LLVM 19 and of LLVM 22, as written and as `llvm-dis`
/// prints it; and the constructs recorded as unsupported are reported by
/// name.
#[test]
#[allow(clippy::cast_precision_loss)] // Sizes for display.
fn accepts_everything_llvm_accepts() {
    let mut report: BTreeMap<String, BTreeSet<&str>> = BTreeMap::new();
    let mut bytes = 0;
    for case in corpus() {
        let module = parsed(case);
        bytes += case.text.len();
        for unsupported in module.module.unsupported() {
            report.entry(unsupported.construct.to_string()).or_default().insert(&case.name);
            assert!(
                !case.from_clang || CLANG_UNSUPPORTED.contains(&unsupported.construct),
                "{}: unexpected unsupported construct {}",
                case.name,
                unsupported.construct
            );
        }
        if let Err(error) = parse(&case.canonical, case.arch) {
            panic!("{}: as printed by llvm-dis: {error}", case.name);
        }
    }
    println!("corpus: {} modules, {:.1} MiB", corpus().len(), bytes as f64 / 1_048_576.0);
    println!("unsupported constructs by name (and the number of modules with each):");
    for (construct, cases) in &report {
        println!("  {construct}: {}", cases.len());
    }
}
